import{n as s,t as r}from"./chunk-DarCEgGK.js";var d=a=>a!==null&&a<=2?`p`:a!==null&&a>=6?`t`:`m`;var t=a=>a===2?`frijol`:`fríjol`;var n={raiz:{p:{nombre:`Raíz`,que:`La parte de abajo, que va debajo de la tierra.`,para:`Sostiene la planta y toma el agua del suelo, con sales que no se ven.`},m:{nombre:`Raíz`,que:`La parte de la planta que crece debajo de la tierra, hacia abajo.`,para:`Sujeta la planta al suelo y absorbe el agua y las sales minerales. También toma el aire que hay entre los granos del suelo: si la tierra se encharca, las raíces se ahogan.`},t:{nombre:`Raíz`,que:`El órgano que fija la planta al suelo; crece hacia abajo y se ramifica.`,para:`Absorbe el agua y las sales minerales, que suben por el tallo hasta las hojas. Respira el aire que hay entre los granos del suelo.`}},tallo:{p:{nombre:`Tallo`,que:`La parte que sostiene las hojas.`,para:`Por el tallo sube el agua hasta las hojas.`},m:{nombre:`Tallo`,que:`La parte que sostiene las hojas, las flores y los frutos. El tronco de un árbol es un tallo grueso y duro.`,para:`Lleva el agua de la raíz a las hojas, y el alimento de las hojas al resto de la planta.`},t:{nombre:`Tallo`,que:`El órgano que sostiene las hojas, las flores y los frutos, y los pone hacia la luz.`,para:`Por sus vasos sube el agua con sales minerales de la raíz a las hojas, y baja el azúcar que hacen las hojas hacia toda la planta.`}},hojas:{p:{nombre:`Hojas`,que:`La parte verde, ancha y plana, que recibe mucha luz.`,para:`Las hojas hacen el alimento de la planta con luz, agua y aire.`},m:{nombre:`Hojas`,que:`Las partes verdes, anchas y planas, que salen del tallo.`,para:`Con la luz del Sol, el agua y el dióxido de carbono del aire, las hojas fabrican el alimento de la planta, y sueltan oxígeno.`},t:{nombre:`Hojas`,que:`Los órganos verdes, anchos y planos, llenos de cloroplastos con clorofila.`,para:`Hacen la fotosíntesis: con la energía de la luz, el agua y el dióxido de carbono fabrican azúcar (glucosa) y sueltan oxígeno. El CO₂ entra y el O₂ sale por los estomas.`}},flor:{p:{nombre:`Flor`,que:`La parte de la planta adulta de la que sale el fruto.`,para:`De la flor sale el fruto. Sin flores no hay frutos.`},m:{nombre:`Flor`,que:`La parte de colores de la planta adulta. En el centro está el estigma, y alrededor, las anteras con el polen.`,para:`De la flor salen el fruto y las semillas. Sus colores llaman a los animales que llevan el polen de una flor a otra.`},t:{nombre:`Flor`,que:`El órgano de la reproducción sexual de la planta: estambres con anteras, pistilo con estigma, estilo y ovario.`,para:`En las anteras se forma el polen; el estigma lo recibe. Los pétalos de colores atraen a los polinizadores. El ovario se vuelve el fruto.`}},fruto:{p:{nombre:`Fruto`,que:`Lo que sale de la flor.`,para:`El fruto guarda las semillas adentro.`},m:{nombre:`Fruto`,que:`Lo que sale de la flor cuando pierde sus pétalos: una bolita que crece y madura.`,para:`Guarda y protege las semillas, y ayuda a que lleguen lejos: los animales se comen la pulpa y botan las semillas.`},t:{nombre:`Fruto`,que:`La estructura que se forma a partir del ovario de la flor.`,para:`Protege las semillas y ayuda a dispersarlas: los animales comen la pulpa y botan las semillas lejos, o el viento y el agua las arrastran.`}},semilla:{p:{nombre:`Semilla`,que:`La parte del fruto de la que nace una planta.`,para:`Guarda una plantita dormida y su comida. Con agua, despierta.`},m:{nombre:`Semilla`,que:`La parte del fruto de la que nace una planta nueva.`,para:`Guarda una planta pequeñita y el alimento que necesita para empezar a crecer.`},t:{nombre:`Semilla`,que:`La estructura que se forma a partir del óvulo fecundado: el embrión, una reserva de alimento y una cubierta que lo protege.`,para:`Guarda el embrión de la planta nueva. Con agua, oxígeno y una temperatura adecuada, germina.`}}};var i={raiz:`🥕`,tallo:`🎋`,hojas:`🍃`,flor:`🌼`,fruto:`🍅`,semilla:`🫘`};var u=(a,o)=>s(r({},n[a][o]),{emoji:i[a]});function c(a,o){let e=t(o);return a===`t`?[{desde:0,titulo:`La semilla`,texto:`El ${e} guarda el embri\xF3n, su reserva de alimento en los dos cotiledones y una cubierta que lo protege.`},{desde:.04,titulo:`Se hincha`,texto:`El ${e} toma agua de la tierra h\xFAmeda y se hincha: el embri\xF3n se activa.`},{desde:.14,titulo:`Sale la radícula`,texto:`La cubierta se rompe y sale primero la radícula, la raíz del embrión, que crece hacia abajo.`},{desde:.3,titulo:`Sube el tallo`,texto:`A la raíz le salen raíces laterales. El tallo crece doblado como un gancho: así se abre paso por la tierra sin dañar su punta.`},{desde:.5,titulo:`Sale a la luz`,texto:`El tallo se endereza y saca los dos cotiledones de la tierra. La cubierta se queda abajo.`},{desde:.72,titulo:`Se abren las hojas`,texto:`Se abren las primeras hojas: la plántula ya hace fotosíntesis. Los cotiledones se gastan y se arrugan.`}]:[{desde:0,titulo:`La semilla`,texto:a===`p`?`El ${e} seco guarda una ${o===1?`plantita`:`matica`} dormida y su comida.`:`La semilla de ${e} guarda una planta peque\xF1ita y su alimento.`},{desde:.04,titulo:`Se hincha`,texto:`El ${e} toma agua de la tierra h\xFAmeda y se hincha.`},{desde:.14,titulo:`Sale la raíz`,texto:`La cubierta se rompe y sale la raíz, que crece hacia abajo.`},{desde:.3,titulo:`Sube el tallo`,texto:`A la raíz le salen raicitas. El tallo crece doblado, como un gancho.`},{desde:.5,titulo:`Sale a la luz`,texto:`El tallo se endereza y saca las dos mitades del ${e}, su comida guardada.`},{desde:.72,titulo:`Se abren las hojas`,texto:a===`p`?`Se abren las primeras hojas. Ahora la matica hace su comida con la luz.`:`Se abren las primeras hojas. Ahora la planta hace su alimento con la luz.`}]}var p=a=>`Sin agua, el ${t(a)} no despierta: sigue seco y duro. Ri\xE9galo.`;function m(a,o){let e=t(o);return{semilla:s(r({},u(`semilla`,a)),{nombre:a===`p`?`El ${e}`:`Semilla`}),raiz:a===`t`?{nombre:`Radícula`,emoji:`🥕`,que:`La raíz del embrión: lo primero que sale de la semilla.`,para:`Crece hacia abajo, fija la plántula y toma el agua. Después le salen raíces laterales.`}:{nombre:`Raíz`,emoji:`🥕`,que:`Lo primero que sale de la semilla.`,para:`Crece hacia abajo y toma el agua. Después le salen raicitas.`},tallo:a===`t`?{nombre:`Tallo`,emoji:`🎋`,que:`Sale después de la raíz y crece hacia arriba, doblado como un gancho.`,para:`Saca de la tierra los cotiledones y las primeras hojas, hacia la luz.`}:{nombre:`Tallo`,emoji:`🎋`,que:`Sale después de la raíz y crece hacia arriba.`,para:a===`p`?`Sube doblado como un gancho y saca las hojas a la luz.`:`Sube doblado como un gancho y saca de la tierra las dos mitades de la semilla y las primeras hojas.`},cotiledones:a===`t`?{nombre:`Cotiledones`,emoji:`🫘`,que:`Las dos mitades de la semilla: las primeras hojas del embrión, gruesas.`,para:`Guardan el alimento de reserva que la plántula gasta mientras no hace fotosíntesis.`}:{nombre:a===`p`?`Las dos mitades`:`Las dos mitades de la semilla`,emoji:`🫘`,que:`Las dos mitades del ${e}.`,para:(a===`p`?`Son su comida guardada: la matica la gasta`:`Son su comida guardada: la planta la gasta`)+` mientras no tiene hojas. Por eso no necesita tierra ni luz para germinar.`},primeras:{nombre:`Primeras hojas`,emoji:`🌱`,que:`Las primeras hojas verdes de la matica.`,para:a===`p`?`Con la luz, hacen la comida de la matica.`:a===`m`?`Con la luz hacen el alimento: la comida guardada ya se acabó.`:`Hacen fotosíntesis: la plántula ya no depende de su reserva.`}}}function b(a,o,e){if(Math.abs(o)<8)return a===`p`?`La luz llega desde arriba: la mata crece derecha.`:`La luz llega desde arriba: el tallo crece derecho.`;let l=o<0?`la izquierda`:`la derecha`;return a===`p`?`La luz llega por ${l}. La mata se dobla hacia la luz.`:a===`m`?`La luz llega s\xF3lo por ${l}${e?`, por la ventanita`:``}: el tallo crece torcido hacia ese lado, buscando la luz.`:`La luz llega s\xF3lo por ${l}${e?`, por la ventana de la caja`:``}: las c\xE9lulas del lado oscuro del tallo crecen m\xE1s y el tallo se dobla hacia la luz. Es el fototropismo.`}var g=a=>a===`p`?`Pasan los días…`:`Pasan los días: el tallo va creciendo…`;function h(a){return a===`t`?[{id:`flor`,titulo:`La flor`,texto:`En la antera de los estambres se forma el polen, que lleva los gametos masculinos. En el centro está el pistilo, con el estigma arriba y el ovario abajo, que guarda los óvulos.`},{id:`abeja`,titulo:`Llega la abeja`,texto:`La abeja visita la flor por su néctar y el polen se le pega al cuerpo.`},{id:`polinizacion`,titulo:`Polinización`,texto:`La abeja vuela a otra flor de la misma especie y deja el polen en el estigma: es polinización cruzada. El polen también lo llevan el viento, las mariposas, los colibríes y los murciélagos.`},{id:`fecundacion`,titulo:`Fecundación`,texto:`El grano de polen forma un tubo que baja por el estilo hasta un óvulo. Allí el gameto masculino se une con el femenino y se forma el cigoto.`},{id:`fruto`,titulo:`Fruto y semillas`,texto:`Los pétalos y los estambres se marchitan y se caen. Cada óvulo fecundado se vuelve una semilla y el ovario crece y se transforma en el fruto.`}]:a===`m`?[{id:`flor`,titulo:`La flor`,texto:`En las anteras, las puntas de los estambres, se forma el polen, un polvito amarillo. En el centro de la flor está el estigma, que recibe el polen.`},{id:`abeja`,titulo:`Llega la abeja`,texto:`La abeja visita la flor por su néctar, un juguito dulce, y el polen de las anteras se le pega al cuerpo.`},{id:`polinizacion`,titulo:`Polinización`,texto:`La abeja vuela a otra flor de la misma clase y deja el polen en su estigma. Eso es la polinización.`},{id:`fruto`,titulo:`Del fruto a la semilla`,texto:`La flor pierde sus pétalos y queda una bolita. La bolita crece y madura: es el fruto, con las semillas adentro.`}]:[{id:`flor`,titulo:`La flor`,texto:`La flor tiene pétalos de colores. En el centro tiene polen, un polvito amarillo.`},{id:`abeja`,titulo:`Llega la abeja`,texto:`La abeja busca el juguito dulce de la flor. El polen se le pega al cuerpo.`},{id:`polinizacion`,titulo:`A otra flor`,texto:`La abeja vuela a otra flor y le deja el polen en el centro.`},{id:`fruto`,titulo:`Sale el fruto`,texto:`La flor pierde sus pétalos y queda una bolita. La bolita crece y madura: es el fruto, con semillas adentro.`}]}function f(a){let o={petalo:{rotulo:a===`t`?`Pétalo`:`Pétalos`,texto:a===`p`?`Los pétalos son de colores: así las abejas encuentran la flor.`:`Los pétalos, casi siempre de colores, atraen a los animales polinizadores.`},polen:{rotulo:`Polen`,texto:a===`p`?`El polen es un polvito amarillo de la flor. La abeja lo lleva a otra flor.`:a===`m`?`El polen es un polvito que se forma en las anteras. Tiene que llegar al estigma de otra flor.`:`El polen se forma en la antera y lleva los gametos masculinos.`},antera:{rotulo:`Antera`,texto:a===`t`?`La antera, en la punta del estambre (la parte masculina): ahí se forma el polen.`:`La antera es la punta de los estambres: ahí se forma el polen.`},estigma:{rotulo:`Estigma`,texto:a===`t`?`El estigma, en la punta del pistilo (la parte femenina): recibe el polen.`:`El estigma está en el centro de la flor: recibe el polen.`}};return a===`t`&&Object.assign(o,{estambre:{rotulo:`Estambre`,texto:`Los estambres son la parte masculina de la flor: un hilo con la antera en la punta.`},estilo:{rotulo:`Estilo`,texto:`El estilo está en medio del pistilo: por él baja el tubo del polen hasta el óvulo.`},ovario:{rotulo:`Ovario`,texto:`El ovario guarda uno o varios óvulos, con el gameto femenino. Después de la fecundación crece y se vuelve el fruto.`},sepalo:{rotulo:`Sépalo`,texto:`Los sépalos son hojitas verdes que protegen el botón de la flor.`}}),a===`p`&&(delete o.antera,o.estigma={rotulo:`Centro de la flor`,texto:`El centro de la flor recibe el polen que trae la abeja.`}),o}var y=a=>a===`p`?`La abeja lleva el polen de una flor a otra.`:a===`m`?`La abeja es un polinizador: lleva el polen de una flor a otra mientras busca néctar.`:`La abeja es un polinizador: busca néctar y, sin quererlo, lleva el polen de la antera de una flor al estigma de otra.`;function j(a,o){let e=a===`t`,l=a===`p`;return{titulo:l?`Un pedacito de hoja, visto muy de cerca.`:e?`Un pedacito de hoja cortado y visto muy de cerca: así se hace la fotosíntesis.`:`Un pedacito de hoja cortado y visto muy de cerca: así hace la hoja el alimento.`,luz:l?`Luz`:`Luz del Sol`,entra:l?`Aire que entra`:e?`CO₂ entra`:`Dióxido de carbono`,sale:l?`Aire que sale`:e?`O₂ sale`:`Oxígeno`,agua:l?`Agua de la raíz`:e?`Agua (H₂O) de la raíz`:`Agua de la raíz`,alimento:e?`Azúcar (glucosa)`:`Alimento`,vapor:`Vapor de agua`,resumen:l?`La hoja toma luz, agua y aire, y hace el alimento de la planta.`:e?`Entran el dióxido de carbono por los estomas y el agua desde la raíz; con la energía de la luz, los cloroplastos fabrican glucosa, un azúcar, y sueltan oxígeno, que sale por los estomas.`:`Con la luz del Sol, la hoja junta el agua que sube de la raíz y el dióxido de carbono del aire, y fabrica el alimento de la planta. Suelta oxígeno.`,noche:e?`De noche no hay fotosíntesis, pero la planta sigue respirando: toma O₂ y suelta CO₂, igual que de día.`:`De noche no hay luz y la hoja no hace alimento. Pero la planta sigue respirando, de día y de noche.`,ecuacion:o!==null&&o>=7?`6 CO₂ + 6 H₂O → C₆H₁₂O₆ + 6 O₂ (con la energía de la luz)`:e?`dióxido de carbono + agua → glucosa + oxígeno (con la energía de la luz)`:null,partes:{estoma:{rotulo:l?`Huequito`:a===`m`?`Huequito (estoma)`:`Estoma`,texto:l?`Un huequito debajo de la hoja: por ahí entra y sale el aire.`:e?`Estoma: poro diminuto de la hoja que se abre y se cierra, sobre todo por debajo; por él entra el dióxido de carbono y salen el oxígeno y el vapor de agua.`:`El estoma es un huequito diminuto, sobre todo por debajo de la hoja: por ahí entra el dióxido de carbono y sale el oxígeno.`},cloroplasto:{rotulo:l?`Partes verdes`:a===`m`?`Bolitas verdes`:`Cloroplastos`,texto:l?`Las bolitas verdes de adentro hacen el alimento con la luz.`:e?`Cloroplasto: parte de las células de las hojas y de los tallos verdes donde ocurre la fotosíntesis. Su clorofila, verde, absorbe la luz: por ella las hojas se ven verdes.`:`Los cloroplastos son las bolitas verdes de las células: con la luz hacen el alimento. Su clorofila es la que hace verdes las hojas.`},nervio:{rotulo:`Nervio`,texto:l?`Por el nervio llega el agua que tomó la raíz.`:e?`Por los vasos del nervio llega el agua que tomó la raíz y subió por el tallo, y por otros sale el azúcar hacia toda la planta.`:`Por el nervio llega el agua que subió desde la raíz, y sale el alimento hacia el resto de la planta.`},epidermis:{rotulo:e?`Epidermis`:`Piel de la hoja`,texto:l?`La piel de la hoja es transparente: deja pasar la luz.`:`La epidermis es la piel de la hoja: una capa de células transparentes que la protege y deja pasar la luz.`},aire:{rotulo:l?`Aire`:`Espacios con aire`,texto:l?`Adentro de la hoja hay huequitos con aire.`:`Entre las células hay espacios con aire: por ahí el dióxido de carbono llega a los cloroplastos y el oxígeno va hacia el estoma.`}}}}var z={partes:a=>a===`p`?`Gira la mata con el dedo. Toca una parte para saber qué es y para qué sirve.`:`Gira la planta con el dedo y toca una parte: raíz, tallo, hojas, flor o fruto.`,germinacion:a=>a===`p`?`Mueve el día y mira despertar la semilla.`:`Mueve los días y mira germinar la semilla: primero la raíz, después el tallo.`,fototropismo:a=>a===`p`?`Mueve la luz y mira la mata.`:`Mueve la luz (o arrastra el sol) y mira hacia dónde crece el tallo.`,polinizacion:()=>`Toca «Siguiente» y sigue a la abeja.`,hoja:a=>a===`p`?`Toca una parte de la hoja.`:`Gira el pedacito de hoja y toca sus partes.`,crecer:()=>`Pasa los días y mira crecer cada mata.`};export{g as a,m as c,u as d,y as f,f as i,p as l,c as n,h as o,z as p,d as r,j as s,b as t,t as u};